import{_ as a,o as l,c as r,a2 as d}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"医疗保障法","description":"","frontmatter":{},"headers":[],"relativePath":"zh/44-医疗保障法.md","filePath":"zh/44-医疗保障法.md"}'),i={name:"zh/44-医疗保障法.md"};function e(o,t,h,n,s,u){return l(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="医疗保障法" tabindex="-1">医疗保障法 <a class="header-anchor" href="#医疗保障法" aria-label="Permalink to &quot;医疗保障法&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>文档编号</td><td>44</td></tr><tr><td>所属模块</td><td>法律体系与治理框架</td></tr><tr><td>核心关键词</td><td>医疗权、共生医疗、修炼损伤救治、生命健康、医保体系</td></tr></tbody></table><h2 id="一、立法目的与基本原则" tabindex="-1">一、立法目的与基本原则 <a class="header-anchor" href="#一、立法目的与基本原则" aria-label="Permalink to &quot;一、立法目的与基本原则&quot;">​</a></h2><p>《医疗保障法》是锚点共生文明五部配套法之一，旨在保障衡元宙内一切生命的健康权与医疗权，建立覆盖万族的共生医疗体系，确保每个生命在伤病时都能获得及时、有效的救治。</p><p>本法确立以下基本原则：</p><table tabindex="0"><thead><tr><th>原则</th><th>内涵</th></tr></thead><tbody><tr><td>健康优先原则</td><td>生命健康是一切进化的基础，国家与文明将保障生命健康置于优先地位</td></tr><tr><td>普遍覆盖原则</td><td>医疗保障覆盖一切生命，不分种族、修为、出身与经济状况</td></tr><tr><td>分级诊疗原则</td><td>建立基层医疗、区域医疗、高阶医疗三级诊疗体系，合理分配医疗资源</td></tr><tr><td>防治结合原则</td><td>预防为主、防治结合，重视修炼损伤的预防与康复</td></tr><tr><td>异族适配原则</td><td>针对不同种族的生理特性提供适配的医疗方案，禁止以人族标准一刀切</td></tr><tr><td>公益属性原则</td><td>基本医疗服务具有公益属性，不得以盈利为目的剥夺生命的救治权</td></tr></tbody></table><h2 id="二、生命健康权的法律保障" tabindex="-1">二、生命健康权的法律保障 <a class="header-anchor" href="#二、生命健康权的法律保障" aria-label="Permalink to &quot;二、生命健康权的法律保障&quot;">​</a></h2><p>本法明确规定，生命健康权是共生宪法赋予每个生命的基本权利，具体包括：</p><ol><li><strong>基本医疗权</strong>：每个生命有权获得免费的基本医疗服务，包括常见病诊治、基础药物、常规体检等。</li><li><strong>急救救治权</strong>：每个生命在突发伤病时有权获得紧急救治，医疗机构不得以任何理由拒绝急救。</li><li><strong>修炼损伤救治权</strong>：修炼者在修炼过程中遭受的能量紊乱、经脉损伤、走火入魔等损伤，有权获得专业救治。</li><li><strong>知情同意权</strong>：患者有权了解自身病情、治疗方案、风险与预后，有权选择或拒绝治疗方案。</li><li><strong>隐私保护权</strong>：患者的医疗信息与身体数据受法律保护，未经患者同意不得泄露或用于其他目的。</li><li><strong>康复保障权</strong>：伤病患者有权获得康复治疗与辅助器具，帮助其恢复劳动与生活能力。</li></ol><h2 id="三、共生医疗体系架构" tabindex="-1">三、共生医疗体系架构 <a class="header-anchor" href="#三、共生医疗体系架构" aria-label="Permalink to &quot;三、共生医疗体系架构&quot;">​</a></h2><p>锚点共生文明的医疗体系分为三级，各层级之间建立转诊与协作机制：</p><table tabindex="0"><thead><tr><th>层级</th><th>名称</th><th>职能</th><th>覆盖范围</th></tr></thead><tbody><tr><td>第一级</td><td>基层医疗站</td><td>常见病诊治、预防保健、基础体检、急救转运</td><td>社区/村落/小型位面</td></tr><tr><td>第二级</td><td>区域医疗中心</td><td>专科诊疗、手术治疗、修炼损伤初步处理、康复</td><td>城市/区域/中型位面</td></tr><tr><td>第三级</td><td>高阶医疗总院</td><td>疑难重症、高阶修炼损伤、意识域疾病、跨种族疑难病</td><td>文明核心/大型位面</td></tr></tbody></table><p>此外，设立&quot;修炼损伤专科&quot;：专门处理修炼过程中的各类损伤，包括能量过载、经脉断裂、心魔入侵、灵魂创伤等，配备精通修炼法则的医疗人员。</p><h2 id="四、医疗保障基金" tabindex="-1">四、医疗保障基金 <a class="header-anchor" href="#四、医疗保障基金" aria-label="Permalink to &quot;四、医疗保障基金&quot;">​</a></h2><p>医疗保障基金是共生医疗体系运行的经济基础，其来源包括：</p><ul><li>公共积累拨款（主要来源）</li><li>联产承包机制中的医疗保障提留</li><li>社会捐赠</li><li>基金投资收益</li></ul><p>基金支付范围包括：基本医疗服务费用、急救费用、修炼损伤救治费用、基本药物费用、康复费用等。患者个人仅需支付少量自付费用，对经济困难者实行减免。</p><h2 id="五、医疗机构与医务人员" tabindex="-1">五、医疗机构与医务人员 <a class="header-anchor" href="#五、医疗机构与医务人员" aria-label="Permalink to &quot;五、医疗机构与医务人员&quot;">​</a></h2><ul><li><strong>公立医疗机构</strong>：由国家或文明共同体设立，承担基本医疗服务与公共卫生职能，经费由医疗保障基金保障。</li><li><strong>私立医疗机构</strong>：由社会力量依法设立，可提供高端医疗服务，但必须接受医疗主管部门监管，不得拒绝急救患者。</li><li><strong>异族医疗机构</strong>：针对特殊种族生理需求设立的专科医疗机构，配备异族医疗人员。</li><li><strong>医务人员权利与义务</strong>：医务人员享有执业保护、合理报酬、职业培训等权利，同时负有救死扶伤、尊重患者、保守医密等义务。</li></ul><h2 id="六、公共卫生与预防" tabindex="-1">六、公共卫生与预防 <a class="header-anchor" href="#六、公共卫生与预防" aria-label="Permalink to &quot;六、公共卫生与预防&quot;">​</a></h2><p>国家建立公共卫生体系，履行以下职能：</p><ol><li>传染病监测与防控，建立跨位面疫情预警机制。</li><li>全民健康体检与健康档案管理。</li><li>修炼安全宣传与修炼损伤预防指导。</li><li>环境卫生与食品药品安全监管。</li><li>突发公共卫生事件应急响应。</li></ol><h2 id="七、法律责任" tabindex="-1">七、法律责任 <a class="header-anchor" href="#七、法律责任" aria-label="Permalink to &quot;七、法律责任&quot;">​</a></h2><p>违反本法规定的行为，视情节轻重承担以下责任：</p><ul><li>医疗机构拒绝急救患者的，责令改正并处罚款，造成严重后果的吊销执业许可。</li><li>医务人员严重不负责任造成患者损害的，承担赔偿责任，情节严重的吊销执业资格。</li><li>医疗机构违规收费、过度医疗的，责令退还费用并处罚款。</li><li>泄露患者医疗隐私的，承担精神损害赔偿，情节严重的追究刑事责任。</li><li>生产销售假药、劣药的，没收违法所得并处罚款，构成犯罪的追究刑事责任。</li></ul><h2 id="结语" tabindex="-1">结语 <a class="header-anchor" href="#结语" aria-label="Permalink to &quot;结语&quot;">​</a></h2><p>《医疗保障法》是锚点共生文明&quot;人人有路&quot;理念在健康领域的体现。它通过建立普遍覆盖的医疗保障体系、设立修炼损伤专科、保障急救救治权，确保每个生命在伤病时都能获得及时救治，为万族共进筑牢健康根基。</p><h2 id="关联文档" tabindex="-1">关联文档 <a class="header-anchor" href="#关联文档" aria-label="Permalink to &quot;关联文档&quot;">​</a></h2><ul><li>40-共生宪法总纲</li><li>38-共生医疗体系</li><li>45-住房保障法</li><li>08-人人有路保障体系</li></ul>',29)])])}const p=a(i,[["render",e]]);export{c as __pageData,p as default};
